const CONTENT={"privacy":"<h2>Privacy Policy</h2><p data-app-title>Stockfish AI Chess</p><p>Privacy policy last updated: October 10, 2026</p><p>Developer: Tughan Y. Karsli<br><span style=\"white-space:nowrap\">Contact: <a href=\"mailto:tughankarsli@gmail.com\">tughankarsli@gmail.com</a></span></p><h3>Games and settings stay on your device</h3><p>Your games, positions, preferences, player name, and saved import usernames are stored locally. The app does not require an account and does not send these records to a developer-operated server. iOS device backups may include app data according to your Apple settings.</p><h3>No advertising or tracking</h3><p>The app contains no advertising, analytics SDK, tracking identifier, or developer-operated telemetry service. Chess engines and the opening book run on your device.</p><h3>Optional internet imports</h3><p>When you request public games from Chess.com or Lichess, the app connects directly to that service. The service receives the requested public username, your IP address, and ordinary network request information. Their own privacy policies apply. Your Chess.com or Lichess password is never requested.</p><h3>Files, clipboard, and sharing</h3><p>The app reads files you select with the document picker and accesses the clipboard when you use an import or copy action. Exported games are sent only to the destination you choose in the iOS share sheet. Those destinations have their own privacy practices.</p><h3>Scan and Analyze photos</h3><p>The camera is used only when you choose Take Photo and grant access. The photo picker gives the app access only to the image you select. Selected photos are processed on your device to recognize the board; they are not uploaded, saved to your photo library, or retained by this app after you close the scanner. The resulting chess position can be saved locally like any other game.</p><h3>Support</h3><p>If you email the developer, your email address and the information you include are used to answer your request and troubleshoot issues. Do not send passwords or private account details. Support correspondence is kept only as needed to resolve and follow up on the request; you can ask for deletion by email.</p><h3>Deleting local data</h3><p>Use Options \u2192 Reset Everything to clear local games and preferences. Turn off the recovery-copy option if you do not want a recoverable copy. Deleting the app removes its local container; exported files and Apple-managed backups are managed separately.</p><h3>Changes</h3><p>This policy will be updated if the app's data practices change. Privacy questions can be sent to tughankarsli@gmail.com.</p>","support":"<h2>Support</h2><p><strong data-app-title>Stockfish AI Chess</strong><br>Developed by Tughan Y. Karsli</p><p>Email <a href=\"mailto:tughankarsli@gmail.com\">tughankarsli@gmail.com</a> for help. Include your app version, iPhone or iPad model, iOS version, and the steps that led to the problem. A screenshot or PGN can help; remove any information you do not want to share.</p>"};
export function installReleaseInfo(open,t=text=>text){
 const dialog=document.createElement("dialog");dialog.id="releaseInfoDialog";dialog.className="release-info-screen options-detail";
 dialog.innerHTML='<div class="dialog-heading"><button type="button" class="options-back" id="releaseInfoBack"><span class="back-chevron" aria-hidden="true"></span><span id="releaseInfoBackLabel">Options</span></button><h2 id="releaseInfoTitle"></h2><button type="button" id="releaseInfoDone">Done</button></div><div id="releaseInfoBody"></div>';document.body.append(dialog);
 document.getElementById("releaseInfoBack").onclick=()=>open("settingsDialog");
 document.getElementById("releaseInfoDone").onclick=()=>dialog.close();
 const titles={privacy:"Privacy Policy",support:"Support"};
 document.querySelectorAll("[data-release-info]").forEach(button=>button.onclick=()=>{const key=button.dataset.releaseInfo;document.getElementById("releaseInfoBackLabel").textContent=t("Options");document.getElementById("releaseInfoDone").textContent=t("Done");document.getElementById("releaseInfoTitle").textContent=titles[key];const body=document.getElementById("releaseInfoBody");body.innerHTML=CONTENT[key];const appTitle=body.querySelector("[data-app-title]");if(appTitle){const version=globalThis.chessNative?.appVersion;const separator=key==="privacy"?" · App version ":" ";appTitle.textContent="Stockfish AI Chess"+(version?separator+version:"");}open(dialog.id);dialog.scrollTop=0;});
}
